import React, { useEffect, useState, useContext } from 'react';
import { useParams, Link } from 'react-router-dom';
import styles from './ProductDetails.module.css';
import { AuthContext } from '../../context/AuthContext';
import { CartContext } from '../../context/CartContext';
import { useNotifications } from '../../context/NotificationContext';
import SupplierSelector from '../../components/SupplierSelector/SupplierSelector';

const formatUTC = (dateString) => {
    return new Intl.DateTimeFormat('ru-RU', {
        timeZone: 'UTC',
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
        hour12: false
    }).format(new Date(dateString));
};

function ProductDetails() {
    const { id } = useParams();
    const [product, setProduct] = useState(null);
    const [loading, setLoading] = useState(true);
    const [suppliers, setSuppliers] = useState([]);
    const { user } = useContext(AuthContext);
    const { addToCart } = useContext(CartContext);
    const { showSuccess, showError, showWarning, showInfo } = useNotifications();

    const [showSupplierSelector, setShowSupplierSelector] = useState(false);
    const [selectedProduct, setSelectedProduct] = useState(null);

    useEffect(() => {
        const url = `http://localhost:5000/api/products/${id}`;
        fetch(url)
            .then(res => res.json())
            .then(data => {
                setProduct(data.data?.product || null);
                setLoading(false);
            })
            .catch(() => {
                setLoading(false);
                showError('Ошибка загрузки продукта');
            });

        fetch('http://localhost:5000/api/suppliers')
            .then(res => res.json())
            .then(data => {
                if (data.success) {
                    setSuppliers(data.data.suppliers || []);
                }
            })
            .catch(() => {
                showWarning('Не удалось загрузить поставщиков');
            });
    }, [id]);

    const handleAddToCart = () => {
        if (!product) return;

        const availableSuppliers = suppliers.filter(s =>
            s.products?.some(p => p.product?._id === product._id)
        );

        if (availableSuppliers.length === 0) {
            showWarning('Товар временно недоступен у поставщиков');
            return;
        }

        if (availableSuppliers.length === 1) {
            const supplier = availableSuppliers[0];
            addToCart(product, supplier._id, supplier.name, 1);
            showSuccess(`Товар "${product.name}" добавлен в корзину от ${supplier.name}!`);
        } else {
            setSelectedProduct(product);
            setShowSupplierSelector(true);
        }
    };

    const handleBuyNow = async () => {
        if (!user) {
            showError('Для заказа необходимо войти в систему');
            return;
        }

        const availableSuppliers = suppliers.filter(s =>
            s.products?.some(p => p.product?._id === product._id)
        );

        if (availableSuppliers.length === 0) {
            showWarning('Товар временно недоступен у поставщиков');
            return;
        }

        try {
            if (availableSuppliers.length === 1) {
                const supplier = availableSuppliers[0];
            } else {
                setSelectedProduct(product);
                setShowSupplierSelector(true);
            }

            showInfo('Проверяем наличие товара...');

            const orderPromise = new Promise(async (resolve, reject) => {
                try {
                    const availabilityCheck = await fetch(`http://localhost:5000/api/suppliers/${supplier._id}`);
                    const supplierData = await availabilityCheck.json();

                    const supplierProduct = supplierData.data?.supplier?.products?.find(
                        p => p.product?._id === product._id
                    );

                    if (!supplierProduct || supplierProduct.stockQuantity < 1) {
                        reject('Товара нет в наличии у поставщика');
                        return;
                    }

                    const purchaseData = {
                        product: product._id,
                        supplier: supplier._id,
                        quantity: 1,
                        purchasePrice: product.currentPrice,
                        status: 'ordered'
                    };

                    const response = await fetch('http://localhost:5000/api/purchases', {
                        method: 'POST',
                        headers: {
                            'Content-Type': 'application/json',
                            'Authorization': `Bearer ${localStorage.getItem('token')}`
                        },
                        body: JSON.stringify(purchaseData)
                    });

                    const data = await response.json();

                    if (data.success) {
                        resolve('Заказ успешно создан!');
                    } else {
                        reject(data.message || 'Ошибка при создании заказа');
                    }
                } catch (error) {
                    reject(error.message);
                }
            });

            const result = await orderPromise;
            showSuccess(result + ' 📦');

        } catch (error) {
            showError(`Ошибка: ${error}`);
        }
    };

    if (loading) {
        return <div className={styles.loading}>Загрузка информации...</div>;
    }

    if (!product) {
        return <div className={styles.error}>Продукт не найден</div>;
    }

    return (
        <div className={styles.details}>
            <Link to="/products" className={styles.back}>← Назад к каталогу</Link>

            <div className={styles.card}>
                <img src={product.imageUrl} alt={product.name} className={styles.image} />
                <div className={styles.info}>
                    <h2>{product.name}</h2>
                    <p><strong>Артикул:</strong> {product.sku}</p>
                    <p><strong>Категория:</strong> {product.category}</p>
                    <p><strong>Для животных:</strong> {product.animalType?.join(', ')}</p>
                    <p><strong>Описание:</strong> {product.description}</p>
                    <p><strong>Цена:</strong> {product.currentPrice} ₽ / {product.unit}</p>
                    <p><strong>Остаток:</strong> {product.stockQuantity} шт.</p>
                    <p><strong>Минимальный уровень склада:</strong> {product.minStockLevel}</p>
                    <p><strong>В наличии:</strong> {product.inStock ? 'Да' : 'Нет'}</p>

                    <p><strong>Добавлен (UTC):</strong> {formatUTC(product.createdAtUTC)}</p>
                    {user && (
                        <p><strong>Добавлен ({user.timezone}):</strong> {product.createdAtLocal}</p>
                    )}
                    <p><strong>Обновлен (UTC):</strong> {formatUTC(product.updatedAtUTC)}</p>
                    {user && (
                        <p><strong>Обновлен ({user.timezone}):</strong> {product.updatedAtLocal}</p>
                    )}

                    <div className={styles.actions}>
                        {user?.role === 'user' && (
                            <>
                                <button
                                    className={styles.buyBtn}
                                    onClick={handleAddToCart}
                                >
                                    В корзину
                                </button>
                                <button
                                    className={styles.orderNowBtn}
                                    onClick={handleBuyNow}
                                >
                                    Заказать сейчас
                                </button>
                            </>
                        )}

                        {user?.role === 'admin' && (
                            <Link
                                to={`/products/edit/${product._id}`}
                                className={styles.editBtn}
                            >
                                Редактировать товар
                            </Link>
                        )}
                    </div>
                </div>
                {showSupplierSelector && selectedProduct && (
                    <SupplierSelector
                        product={selectedProduct}
                        suppliers={suppliers}
                        onSelect={(supplier) => {
                            addToCart(selectedProduct, supplier.id, supplier.name, 1);
                            showSuccess(`Товар "${selectedProduct.name}" добавлен в корзину от ${supplier.name}! 🛒`);
                            setShowSupplierSelector(false);
                            setSelectedProduct(null);
                        }}
                        onCancel={() => {
                            setShowSupplierSelector(false);
                            setSelectedProduct(null);
                            showInfo('Выбор поставщика отменен');
                        }}
                    />
                )}
            </div>
        </div>
    );
}

export default ProductDetails;
